import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";var i=JSON.parse(`{"title":"Node.js 环境的安装","description":"","frontmatter":{},"headers":[],"relativePath":"nodejs/environment.md","filePath":"nodejs/environment.md"}`),a={name:`nodejs/environment.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="node-js-环境的安装" tabindex="-1">Node.js 环境的安装 <a class="header-anchor" href="#node-js-环境的安装" aria-label="Permalink to “Node.js 环境的安装”">​</a></h1><p>如果希望通过 Node.js 来运行 Javascript 代码，则必须在计算机上安装 Node.js 环境才行。</p><p>安装包可以从 Node.js 的官网首页直接下载，进入到 Node.js 的<a href="https://nodejs.org/en/" target="_blank" rel="noreferrer">官网首页</a>，</p><p>点击绿色的按钮，下载所需的版本后，双击直接安装即可。</p><h2 id="区分-lts-版本和-current-版本的不同" tabindex="-1">区分 LTS 版本和 Current 版本的不同 <a class="header-anchor" href="#区分-lts-版本和-current-版本的不同" aria-label="Permalink to “区分 LTS 版本和 Current 版本的不同”">​</a></h2><ul><li><p>LTS 为长期稳定版，对于追求稳定性的企业级项目来说，推荐安装 LTS 版本的 Node.js。</p></li><li><p>Current 为新特性尝鲜版，对热衷于尝试新特性的用户来说，推荐安装 Current 版本的 Node.js。但是，Current 版本中可<br> 能存在隐藏的 Bug 或安全性漏洞，因此不推荐在企业级项目中使用 Current 版本的 Node.js</p></li></ul><h2 id="查看已安装的-node-js-的版本号" tabindex="-1">查看已安装的 Node.js 的版本号 <a class="header-anchor" href="#查看已安装的-node-js-的版本号" aria-label="Permalink to “查看已安装的 Node.js 的版本号”">​</a></h2><ul><li><p>打开终端，在终端输入命令 node –v 后，按下回车键，即可查看已安装的 Node.js 的版本号。</p></li><li><p>Windows 系统快速打开终端的方式：<br> 使用快捷键（Windows徽标键 + R）打开运行面板，输入 cmd 后直接回车，即可打开终端。</p></li></ul><h2 id="什么是终端" tabindex="-1">什么是终端 <a class="header-anchor" href="#什么是终端" aria-label="Permalink to “什么是终端”">​</a></h2><p>终端（英文：Terminal）是专门为开发人员设计的，用于实现人机交互的一种方式。</p><p>作为一名合格的程序员，我们有必要识记一些常用的终端命令，来辅助我们更好的操作与使用计算机。</p><h2 id="在-node-js-环境中执行-javascript-代码" tabindex="-1">在 Node.js 环境中执行 JavaScript 代码 <a class="header-anchor" href="#在-node-js-环境中执行-javascript-代码" aria-label="Permalink to “在 Node.js 环境中执行 JavaScript 代码”">​</a></h2><ol><li><p>打开终端</p></li><li><p>输入 node 要执行的js文件的路径</p></li></ol><h2 id="终端中的快捷键" tabindex="-1">终端中的快捷键 <a class="header-anchor" href="#终端中的快捷键" aria-label="Permalink to “终端中的快捷键”">​</a></h2><p>在 Windows 的 powershell 或 cmd 终端中，我们可以通过如下快捷键，来提高终端的操作效率：</p><ol><li><p>使用 ↑ 键，可以快速定位到上一次执行的命令</p></li><li><p>使用 tab 键，能够快速补全路径</p></li><li><p>使用 esc 键，能够快速清空当前已输入的命令</p></li><li><p>输入 cls 命令，可以清空终端</p></li></ol>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};